package com.bank.storage.retention;

import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;

@Component
@Slf4j
public class RetentionAdvisor {

    // Recommend a segment size that keeps per-delete I/O bursts bounded on EBS.
    public long recommendSegmentBytes(long ingestBytesPerSec, int provisionedIops, boolean isEbs) {
        // On EBS, prefer smaller segments so each delete is a smaller random-I/O burst.
        long base = isEbs ? 256L * 1024 * 1024 : 1024L * 1024 * 1024;
        if (isEbs && provisionedIops < 3000) {
            base = 128L * 1024 * 1024; // even smaller when IOPS budget is tight
            log.warn("Low IOPS on EBS — using 128MB segments to reduce delete bursts");
        }
        log.info("Recommended segment.bytes={} (ebs={}, iops={})", base, isEbs, provisionedIops);
        return base;
    }
}
