// ─── File: demo/RetentionCleanupDemo.java ───
package com.bank.storage.demo;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RetentionCleanupDemo {

    private static final Logger log = Logger.getLogger(RetentionCleanupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Large 1GB segments on EBS (spiky) ===");
        PartitionLog big = buildLog(1024, 8);          // 8 x 1GB segments
        StorageDevice ebs = new StorageDevice(true, 3000); // EBS, 3000 IOPS budget
        new RetentionCleaner().cleanupBurst(big, ebs, log);

        log.info("=== Smaller 256MB segments on EBS (smoother) ===");
        PartitionLog small = buildLog(256, 32);        // 32 x 256MB segments = same data
        StorageDevice ebs2 = new StorageDevice(true, 3000);
        new RetentionCleaner().cleanupStaggered(small, ebs2, log);

        log.info("=== Same large segments on local NVMe (for contrast) ===");
        PartitionLog big2 = buildLog(1024, 8);
        StorageDevice nvme = new StorageDevice(false, 100000);
        new RetentionCleaner().cleanupBurst(big2, nvme, log);
    }

    private static PartitionLog buildLog(int segMB, int count) {
        List<Segment> segs = new ArrayList<>();
        for (int i = 0; i < count; i++) segs.add(new Segment("seg-" + i, segMB, /*expired*/ i < count - 2));
        return new PartitionLog(segs);
    }
}

// ─── Would be in Segment.java in a real project ───
class Segment {
    final String name; final int sizeMB; final boolean expired;
        Segment(String name, int sizeMB, boolean expired) { this.name = name;
        this.sizeMB = sizeMB
        this.expired = expired; }
}

// ─── Would be in PartitionLog.java in a real project ───
class PartitionLog {
    final List<Segment> segments;
    PartitionLog(List<Segment> segments) { this.segments = segments; }
    List<Segment> expiredSegments() {
        List<Segment> r = new ArrayList<>();
        for (Segment s : segments) if (s.expired) r.add(s);
        return r;
    }
}

// ─── Would be in StorageDevice.java in a real project ───
class StorageDevice {
    private final boolean ebs;
    private int iopsBudget;
        StorageDevice(boolean ebs, int iopsBudget) { this.ebs = ebs;
        this.iopsBudget = iopsBudget; }

    // Deleting a segment costs random metadata I/O; EBS amplifies it.
    int deleteCost(int sizeMB) {
        int localOps = sizeMB / 4 + 50;              // block deallocations + inode updates
        int cost = ebs ? localOps * 3 : localOps;    // storage-layer amplification on EBS
        iopsBudget -= cost;
        return cost;
    }
    boolean throttled() { return ebs && iopsBudget < 0; }
    int remainingIops() { return iopsBudget; }
    boolean isEbs() { return ebs; }
}

// ─── Would be in RetentionCleaner.java in a real project ───
class RetentionCleaner {

    // Scan -> delete ALL expired at once -> sleep: one big burst.
    void cleanupBurst(PartitionLog logTopic, StorageDevice dev, Logger log) {
        int totalCost = 0;
        for (Segment s : logTopic.expiredSegments()) {
            totalCost += dev.deleteCost(s.sizeMB);
            // page cache for this segment is invalidated here too
        }
        report(dev, totalCost, "BURST", log);
    }

    // Scan -> delete a few -> sleep -> repeat: staggered, smaller bursts.
    void cleanupStaggered(PartitionLog logTopic, StorageDevice dev, Logger log) {
        int maxCost = 0;
        List<Segment> expired = logTopic.expiredSegments();
        for (int i = 0; i < expired.size(); i += 4) {           // batch of 4 per cycle
            int cycleCost = 0;
            for (int j = i; j < Math.min(i + 4, expired.size()); j++)
                cycleCost += dev.deleteCost(expired.get(j).sizeMB);
            maxCost = Math.max(maxCost, cycleCost);
            // sleep(log.retention.check.interval.ms) between cycles
        }
        report(dev, maxCost, "STAGGERED(peak per cycle)", log);
    }

    private void report(StorageDevice dev, int cost, String mode, Logger log) {
        if (dev.throttled()) {
            log.severe(mode + " delete cost=" + cost + " IOPS EXHAUSTED on EBS (remaining "
                    + dev.remainingIops() + ") -> THROTTLED, prolonged latency spike");
        } else {
            log.info(mode + " delete cost=" + cost + " within budget (remaining "
                    + dev.remainingIops() + ", ebs=" + dev.isEbs() + ") -> contained");
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
